/*
 * Writes information about the original source file and the
 * temporary preprocessed file used as input for the scanner.
 */
static void write_input_slide(
    FILE *file,
    const char *source_filename,
    const char *preprocessed_filename
) {

    fprintf(file,
        "\\begin{frame}{Processed Files}\n"
        "\n"
        "\\begin{block}{Source file}\n"
        "\\texttt{"
    );

    write_latex_escaped(file, source_filename);

    fprintf(file,
        "}\n"
        "\\end{block}\n"
        "\n"
        "\\begin{block}{File after preprocessing}\n"
        "\\texttt{"
    );

    write_latex_escaped(file, preprocessed_filename);

    fprintf(file,
        "}\n"
        "\\end{block}\n"
        "\n"
        "The scanner uses the temporary file generated by "
        "the preprocessor as its actual input.\n"
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Writes a summary table containing the lexical categories
 * found by the scanner.
 */
static void write_statistics_slide(
    FILE *file,
    const BeamerStats *stats
) {

    fprintf(file,
        "\\begin{frame}{Lexical Analysis Summary}\n"
        "\n"
        "\\centering\n"
        "\n"
        "\\begin{tabular}{lr}\n"
        "\\textbf{Category} & "
        "\\textbf{Count} \\\\ \\hline\n"
        "\n"
        "Keywords & %zu \\\\\n"
        "Identifiers & %zu \\\\\n"
        "Constants & %zu \\\\\n"
        "String literals & %zu \\\\\n"
        "Operators & %zu \\\\\n"
        "Punctuators & %zu \\\\\n"
        "Lexical errors & %zu \\\\\n"
        "\\hline\n"
        "\\textbf{Total} & \\textbf{%zu} \\\\\n"
        "\\end{tabular}\n"
        "\n"
        "\\end{frame}\n"
        "\n",

        stats->keyword_count,
        stats->identifier_count,
        stats->constant_count,
        stats->string_literal_count,
        stats->operator_count,
        stats->punctuator_count,
        stats->error_count,
        stats->total_tokens
    );
}


