/*
 * Writes the lexical-error slide.
 */
static void write_error_slide(
    FILE *file,
    const Token *tokens,
    size_t token_count
) {
    size_t error_count = 0;

    for (size_t i = 0; i < token_count; i++) {

        if (tokens[i].category == CAT_ERROR) {
            error_count++;
        }
    }

    fprintf(file,
        "\\begin{frame}{Lexical Errors}\n"
        "\n"
    );

    if (error_count == 0) {

        fprintf(file,
            "\\begin{block}{Result}\n"
            "No lexical errors were found.\n"
            "\\end{block}\n"
        );

    } else {

        fprintf(file,
            "%zu lexical errors were found.\n"
            "\n"
            "\\vspace{0.3cm}\n"
            "\n"
            "\\begin{tabular}{lll}\n"
            "\\textbf{Lexeme} & "
            "\\textbf{Line} & "
            "\\textbf{Column} \\\\ \\hline\n",
            error_count
        );

        for (size_t i = 0; i < token_count; i++) {

            if (tokens[i].category != CAT_ERROR) {
                continue;
            }

            fprintf(file, "\\texttt{");

            write_latex_escaped(
                file,
                tokens[i].lexeme
            );

            fprintf(file,
                "} & %d & %d \\\\\n",
                tokens[i].line,
                tokens[i].column
            );
        }

        fprintf(file,
            "\\end{tabular}\n"
        );
    }

    fprintf(file,
        "\n"
        "\\end{frame}\n"
        "\n"
    );
}


/*
 * Writes one sector of the dynamic pie chart.
 */
static void write_pie_sector(
    FILE *file,
    double start_angle,
    double end_angle,
    const char *color
) {
    if (end_angle <= start_angle) {
        return;
    }

    fprintf(file,
        "\\path[\n"
        "    fill=%s,\n"
        "    draw=white,\n"
        "    thick\n"
        "]\n"
        "(axis cs:%.4f,0) --\n"
        "(axis cs:%.4f,1)\n"
        "plot[\n"
        "    domain=%.4f:%.4f,\n"
        "    samples=30\n"
        "] (axis cs:\\x,1)\n"
        "-- (axis cs:%.4f,0)\n"
        "-- cycle;\n"
        "\n",

        color,
        start_angle,
        start_angle,
        start_angle,
        end_angle,
        end_angle
    );
}


/*
 * Writes a dynamic pie chart based on lexical categories.
 */
static void write_pie_chart(
    FILE *file,
    const BeamerStats *stats
) {

    fprintf(file,
        "\\begin{frame}{Distribution of Lexical Categories}\n"
        "\n"
    );

    if (stats->total_tokens == 0) {

        fprintf(file,
            "\\centering\n"
            "\n"
            "No tokens were found to display.\n"
            "\n"
            "\\end{frame}\n"
            "\n"
        );

        return;
    }

    double angle = 0.0;

    double keyword_angle =
        360.0 *
        (double) stats->keyword_count /
        (double) stats->total_tokens;

    double identifier_angle =
        360.0 *
        (double) stats->identifier_count /
        (double) stats->total_tokens;

    double constant_angle =
        360.0 *
        (double) stats->constant_count /
        (double) stats->total_tokens;

    double string_angle =
        360.0 *
        (double) stats->string_literal_count /
        (double) stats->total_tokens;

    double operator_angle =
        360.0 *
        (double) stats->operator_count /
        (double) stats->total_tokens;

    double punctuator_angle =
        360.0 *
        (double) stats->punctuator_count /
        (double) stats->total_tokens;

    double error_angle =
        360.0 *
        (double) stats->error_count /
        (double) stats->total_tokens;

    fprintf(file,
        "\\centering\n"
        "\n"
        "\\begin{tikzpicture}\n"
        "\n"
        "\\begin{polaraxis}[\n"
        "    hide axis,\n"
        "    xmin=0,\n"
        "    xmax=360,\n"
        "    ymin=0,\n"
        "    ymax=1,\n"
        "    width=7cm,\n"
        "    height=7cm\n"
        "]\n"
        "\n"
    );

    write_pie_sector(
        file,
        angle,
        angle + keyword_angle,
        "blue!65"
    );
    angle += keyword_angle;

    write_pie_sector(
        file,
        angle,
        angle + identifier_angle,
        "green!60"
    );
    angle += identifier_angle;

    write_pie_sector(
        file,
        angle,
        angle + constant_angle,
        "orange!70"
    );
    angle += constant_angle;

    write_pie_sector(
        file,
        angle,
        angle + string_angle,
        "cyan!60"
    );
    angle += string_angle;

    write_pie_sector(
        file,
        angle,
        angle + operator_angle,
        "violet!60"
    );
    angle += operator_angle;

    write_pie_sector(
        file,
        angle,
        angle + punctuator_angle,
        "yellow!70"
    );
    angle += punctuator_angle;

    write_pie_sector(
        file,
        angle,
        angle + error_angle,
        "red!65"
    );

    fprintf(file,
        "\\end{polaraxis}\n"
        "\n"
        "\\end{tikzpicture}\n"
        "\n"
        "\\scriptsize\n"
        "\n"
        "\\begin{tabular}{lll}\n"
        "\\textcolor{blue!65}{\\rule{0.25cm}{0.25cm}} "
        "Keywords: %zu &\n"
        "\\textcolor{green!60}{\\rule{0.25cm}{0.25cm}} "
        "Identifiers: %zu &\n"
        "\\textcolor{orange!70}{\\rule{0.25cm}{0.25cm}} "
        "Constants: %zu \\\\[0.15cm]\n"
        "\n"
        "\\textcolor{cyan!60}{\\rule{0.25cm}{0.25cm}} "
        "Strings: %zu &\n"
        "\\textcolor{violet!60}{\\rule{0.25cm}{0.25cm}} "
        "Operators: %zu &\n"
        "\\textcolor{yellow!70}{\\rule{0.25cm}{0.25cm}} "
        "Punctuators: %zu \\\\[0.15cm]\n"
        "\n"
        "\\textcolor{red!65}{\\rule{0.25cm}{0.25cm}} "
        "Errors: %zu & &\n"
        "\\end{tabular}\n"
        "\n"
        "\\end{frame}\n"
        "\n",

        stats->keyword_count,
        stats->identifier_count,
        stats->constant_count,
        stats->string_literal_count,
        stats->operator_count,
        stats->punctuator_count,
        stats->error_count
    );
}


